using System;using System.Text;using System.Diagnostics;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Runtime.InteropServices;using System.Threading;
class HumanRegionPreview {
 struct R{public int l,t,r,b;}
 [DllImport("user32.dll")]static extern IntPtr GetDlgItem(IntPtr w,int id);
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr w,uint m,IntPtr a,IntPtr b);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr SendMessage(IntPtr w,uint m,IntPtr a,string b);
 [DllImport("user32.dll")]static extern bool PostMessage(IntPtr w,uint m,IntPtr a,IntPtr b);
 [DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr w,out R r);
 [DllImport("user32.dll")]static extern bool PrintWindow(IntPtr w,IntPtr dc,uint f);
 [DllImport("user32.dll")]static extern bool SetWindowPos(IntPtr w,IntPtr z,int x,int y,int width,int height,uint flags);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindow(string c,string t);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr SendMessage(IntPtr w,uint m,IntPtr a,StringBuilder b);
 static void Click(IntPtr w,int id){SendMessage(GetDlgItem(w,id),0xf5,IntPtr.Zero,IntPtr.Zero);Thread.Sleep(300);}
 static void Shot(IntPtr w,string path){R r;GetWindowRect(w,out r);using(var b=new Bitmap(r.r-r.l,r.b-r.t))using(var g=Graphics.FromImage(b)){var dc=g.GetHdc();PrintWindow(w,dc,2);g.ReleaseHdc(dc);b.Save(path,ImageFormat.Png);}}
 static int Main(string[] a){Directory.CreateDirectory(a[1]);string profile=Path.Combine(a[1],"profile");Directory.CreateDirectory(profile);var start=new ProcessStartInfo(a[0]){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(a[0])};start.EnvironmentVariables["LOCALAPPDATA"]=profile;var p=Process.Start(start);IntPtr w=IntPtr.Zero;try{for(int i=0;i<180;i++){p.Refresh();w=p.MainWindowHandle;if(w!=IntPtr.Zero&&GetDlgItem(w,1061)!=IntPtr.Zero)break;Thread.Sleep(100);}if(w==IntPtr.Zero)throw new Exception("Application did not open");Thread.Sleep(800);SendMessage(GetDlgItem(w,1002),0xc,IntPtr.Zero,"39.9,116.4");Click(w,1003);Shot(w,Path.Combine(a[1],"region-overview-zh.png"));for(int page=0;page<4;page++){Click(w,1061+page);Shot(w,Path.Combine(a[1],"region-page-"+page+"-zh.png"));}Click(w,1065);var original=FindWindow("WorldMapExplorerRouteNotes",null);if(original==IntPtr.Zero)throw new Exception("Original record did not open");var raw=new StringBuilder(20000);SendMessage(GetDlgItem(original,1),0xd,new IntPtr(raw.Capacity),raw);var rawText=raw.ToString();if(!rawText.Contains("NOAA")||!rawText.Contains("GeoNames")||!rawText.Contains("Z9800")||rawText.Contains("\r\r\n"))throw new Exception("Original record content or line endings invalid");Shot(original,Path.Combine(a[1],"original-record-zh.png"));Click(original,2);Click(w,1061);Click(w,1024);Shot(w,Path.Combine(a[1],"region-overview-en.png"));Click(w,1063);Shot(w,Path.Combine(a[1],"region-places-en.png"));SetWindowPos(w,IntPtr.Zero,10,10,1024,650,4);Thread.Sleep(400);Click(w,1061);Shot(w,Path.Combine(a[1],"region-small-en.png"));Click(w,1011);Shot(w,Path.Combine(a[1],"vector-region-small-en.png"));Console.WriteLine("PASS: summary, four pages, English, small window and vector layer captured");return 0;}catch(Exception e){Console.WriteLine("FAIL: "+e);return 1;}finally{if(!p.HasExited){PostMessage(w,0x10,IntPtr.Zero,IntPtr.Zero);if(!p.WaitForExit(8000))p.Kill();}}}
}
